CREATE POLICY "account_media_read" ON storage.objects FOR SELECT USING (bucket_id = 'account-media');
CREATE POLICY "account_media_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'account-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "account_media_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'account-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "account_media_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'account-media' AND (storage.foldername(name))[1] = auth.uid()::text);